	var high float64
	var low float64
	var close_ float64
	var tmp float64
	ad := sp.ad
	var cur_outReal float64
	fastEMA := sp.fastEMA
	slowEMA := sp.slowEMA
	high = inHigh
	low = inLow
	tmp = high - low
	close_ = inClose
	if tmp > 0.0 {
		ad += float64((close_ - low - (high - close_)) / tmp * inVolume)
	}
	fastEMA = math.FMA(sp.one_minus_fastk, fastEMA, float64(sp.fastk*ad))
	slowEMA = math.FMA(sp.one_minus_slowk, slowEMA, float64(sp.slowk*ad))
