// is empty, too short or sharing memory. A slice whose capacity a three-index
// expression cut, as slices.Clip does, can escape the sharing check.
func (c *Core) ADOSCOpenAndFill(inHigh, inLow, inClose, inVolume []float64, optInFastPeriod, optInSlowPeriod int, outReal []float64) (*ADOSCStream, OutRange, error) {
	if !fitsInt32(optInFastPeriod) {
		return nil, OutRange{}, BadParam
	}
	if !fitsInt32(optInSlowPeriod) {
		return nil, OutRange{}, BadParam
	}
	if len(inHigh) > IndexMax+1 {
		return nil, OutRange{}, OutOfRangeEndIndex
	}
	lookback := int(c.adoscLookback(int32(optInFastPeriod), int32(optInSlowPeriod)))
	if lookback < 0 {
		return nil, OutRange{}, BadParam
	}
	if len(inLow) != len(inHigh) {
		return nil, OutRange{}, BadParam
	}
	if len(inClose) != len(inHigh) {
		return nil, OutRange{}, BadParam
	}
	if len(inVolume) != len(inHigh) {
		return nil, OutRange{}, BadParam
	}
	outLen := max(len(inHigh)-lookback, 0)
	if len(outReal) == 0 || len(outReal) < outLen {
		return nil, OutRange{}, BadParam
	}
	if sameStart(outReal, inHigh) || sameStart(outReal, inLow) || sameStart(outReal, inClose) || sameStart(outReal, inVolume) {
		return nil, OutRange{}, BadParam
	}
	if outLen > 0 && (overlaps(outReal, inHigh) || overlaps(outReal, inLow) || overlaps(outReal, inClose) || overlaps(outReal, inVolume)) {
		return nil, OutRange{}, BadParam
	}
	var outBegIdx, outNBElement int32
	sp, err := c.adoscOpenAndFillInternal(inHigh, inLow, inClose, inVolume, 0, int32(optInFastPeriod), int32(optInSlowPeriod), &outBegIdx, &outNBElement, outReal)
	if err != nil {
		return nil, OutRange{}, err
	}
	return sp, OutRange{BegIdx: int(outBegIdx), NBElement: int(outNBElement)}, nil
}
